begin;

drop policy if exists daily_reports_staff_insert on public.daily_reports;
drop policy if exists daily_reports_staff_update on public.daily_reports;

alter table public.daily_reports add column if not exists published_by uuid references auth.users(id);
alter table public.daily_reports add column if not exists published_channel text;

create or replace function public.generate_daily_report_draft(p_reservation_cat_id uuid,p_report_date date) returns public.daily_reports language plpgsql security definer set search_path=public,pg_temp as $$
declare v_org uuid;v_cat_name text;v_checkin date;v_checkout date;v_day_id uuid;v_content jsonb;v_revision jsonb;v public.daily_reports%rowtype;
begin
 select rc.organization_id,c.name,(coalesce(r.actual_check_in_at,r.expected_check_in_at) at time zone 'Asia/Taipei')::date,(r.expected_check_out_at at time zone 'Asia/Taipei')::date
 into v_org,v_cat_name,v_checkin,v_checkout
 from public.reservation_cats rc join public.cats c on c.id=rc.cat_id and c.organization_id=rc.organization_id join public.reservations r on r.id=rc.reservation_id and r.organization_id=rc.organization_id
 where rc.id=p_reservation_cat_id;
 if v_org is null or not public.current_user_has_org(v_org,array['owner','manager','staff']) then raise exception 'stay cat not found';end if;
 if p_report_date<v_checkin or p_report_date>=v_checkout then raise exception 'report date must be within boarding dates';end if;
 select id into v_day_id from public.care_days where organization_id=v_org and reservation_cat_id=p_reservation_cat_id and care_date=p_report_date;
 v_content=jsonb_build_object(
  'schema_version',1,'cat_name',v_cat_name,'report_date',p_report_date,'public_message','',
  'meals',coalesce((select jsonb_agg(jsonb_build_object('time',to_char(coalesce(actual_feeding_at,scheduled_at) at time zone 'Asia/Taipei','HH24:MI'),'label',label,'status',status,'offered_quantity',offered_quantity,'consumed_quantity',consumed_quantity,'remaining_quantity',remaining_quantity,'unit',unit) order by coalesce(actual_feeding_at,scheduled_at,created_at)) from public.meal_records where organization_id=v_org and care_day_id=v_day_id),'[]'::jsonb),
  'water',coalesce((select jsonb_agg(jsonb_build_object('time',to_char(observed_at at time zone 'Asia/Taipei','HH24:MI'),'observation',observation,'amount',amount,'unit',unit,'water_replaced',water_replaced) order by observed_at) from public.water_records where organization_id=v_org and care_day_id=v_day_id),'[]'::jsonb),
  'urination',coalesce((select jsonb_agg(jsonb_build_object('time',to_char(observed_at at time zone 'Asia/Taipei','HH24:MI'),'observation_state',observation_state,'clump_count',clump_count,'clump_size',clump_size,'color',color,'suspected_blood',suspected_blood,'repeated_visits',repeated_visits,'unusual_behavior',unusual_behavior) order by observed_at) from public.urination_records where organization_id=v_org and care_day_id=v_day_id),'[]'::jsonb),
  'defecation',coalesce((select jsonb_agg(jsonb_build_object('time',to_char(observed_at at time zone 'Asia/Taipei','HH24:MI'),'observation_state',observation_state,'quantity',quantity,'consistency',consistency,'unusual_color',unusual_color,'suspected_blood',suspected_blood) order by observed_at) from public.defecation_records where organization_id=v_org and care_day_id=v_day_id),'[]'::jsonb),
  'activity',coalesce((select jsonb_agg(jsonb_build_object('time',to_char(observed_at at time zone 'Asia/Taipei','HH24:MI'),'activity',activity,'mood',mood,'social_interaction',social_interaction,'hiding_behavior',hiding_behavior,'vomiting',vomiting,'scratching',scratching,'visible_injury',visible_injury,'cleaning_completed',cleaning_completed) order by observed_at) from public.activity_records where organization_id=v_org and care_day_id=v_day_id),'[]'::jsonb),
  'medications',coalesce((select jsonb_agg(jsonb_build_object('time',to_char(mr.scheduled_at at time zone 'Asia/Taipei','HH24:MI'),'name',mo.name,'status',mr.status,'actual_time',case when mr.actual_administered_at is not null then to_char(mr.actual_administered_at at time zone 'Asia/Taipei','HH24:MI') end) order by mr.scheduled_at) from public.medication_records mr join public.medication_orders mo on mo.id=mr.medication_order_id and mo.organization_id=mr.organization_id where mr.organization_id=v_org and mo.reservation_cat_id=p_reservation_cat_id and (mr.scheduled_at at time zone 'Asia/Taipei')::date=p_report_date),'[]'::jsonb),
  'events',coalesce((select jsonb_agg(jsonb_build_object('time',to_char(event_at at time zone 'Asia/Taipei','HH24:MI'),'category',category,'severity',severity,'status',status) order by event_at) from public.abnormal_events where organization_id=v_org and reservation_cat_id=p_reservation_cat_id and (event_at at time zone 'Asia/Taipei')::date=p_report_date),'[]'::jsonb)
 );
 v_revision=jsonb_build_object('care_day_id',v_day_id,'generated_at',now(),'meal_versions',coalesce((select jsonb_agg(jsonb_build_object('id',id,'version',version)) from public.meal_records where organization_id=v_org and care_day_id=v_day_id),'[]'::jsonb),'water_versions',coalesce((select jsonb_agg(jsonb_build_object('id',id,'version',version)) from public.water_records where organization_id=v_org and care_day_id=v_day_id),'[]'::jsonb),'urination_versions',coalesce((select jsonb_agg(jsonb_build_object('id',id,'version',version)) from public.urination_records where organization_id=v_org and care_day_id=v_day_id),'[]'::jsonb),'defecation_versions',coalesce((select jsonb_agg(jsonb_build_object('id',id,'version',version)) from public.defecation_records where organization_id=v_org and care_day_id=v_day_id),'[]'::jsonb),'activity_versions',coalesce((select jsonb_agg(jsonb_build_object('id',id,'version',version)) from public.activity_records where organization_id=v_org and care_day_id=v_day_id),'[]'::jsonb),'medication_versions',coalesce((select jsonb_agg(jsonb_build_object('id',mr.id,'version',mr.version)) from public.medication_records mr join public.medication_orders mo on mo.id=mr.medication_order_id and mo.organization_id=mr.organization_id where mr.organization_id=v_org and mo.reservation_cat_id=p_reservation_cat_id and (mr.scheduled_at at time zone 'Asia/Taipei')::date=p_report_date),'[]'::jsonb),'event_versions',coalesce((select jsonb_agg(jsonb_build_object('id',id,'version',version)) from public.abnormal_events where organization_id=v_org and reservation_cat_id=p_reservation_cat_id and (event_at at time zone 'Asia/Taipei')::date=p_report_date),'[]'::jsonb));
 select * into v from public.daily_reports where organization_id=v_org and reservation_cat_id=p_reservation_cat_id and report_date=p_report_date for update;
 if found then
  if v.status<>'draft' then raise exception 'approved or published report cannot be regenerated';end if;
  update public.daily_reports set owner_content=v_content||jsonb_build_object('public_message',coalesce(v.owner_content->>'public_message','')),internal_source_revision=v_revision,updated_by=auth.uid() where id=v.id returning * into v;
 else
  insert into public.daily_reports(organization_id,reservation_cat_id,report_date,status,owner_content,internal_source_revision,created_by,updated_by) values(v_org,p_reservation_cat_id,p_report_date,'draft',v_content,v_revision,auth.uid(),auth.uid()) returning * into v;
 end if;
 return v;
end $$;
revoke all on function public.generate_daily_report_draft(uuid,date) from public;grant execute on function public.generate_daily_report_draft(uuid,date) to authenticated;

create or replace function public.save_daily_report_message(p_report_id uuid,p_public_message text,p_expected_version integer) returns public.daily_reports language plpgsql security definer set search_path=public,pg_temp as $$
declare v public.daily_reports%rowtype;begin select * into v from public.daily_reports where id=p_report_id for update;if not found or not public.current_user_has_org(v.organization_id,array['owner','manager','staff']) then raise exception 'report not found';end if;if v.version<>p_expected_version then raise exception 'report changed; reload' using errcode='40001';end if;if v.status<>'draft' then raise exception 'only draft report can be edited';end if;if length(coalesce(p_public_message,''))>2000 then raise exception 'public message is too long';end if;update public.daily_reports set owner_content=jsonb_set(owner_content,'{public_message}',to_jsonb(trim(coalesce(p_public_message,''))),true),updated_by=auth.uid() where id=v.id returning * into v;return v;end $$;
revoke all on function public.save_daily_report_message(uuid,text,integer) from public;grant execute on function public.save_daily_report_message(uuid,text,integer) to authenticated;

create or replace function public.approve_daily_report(p_report_id uuid,p_expected_version integer) returns public.daily_reports language plpgsql security definer set search_path=public,pg_temp as $$
declare v public.daily_reports%rowtype;begin select * into v from public.daily_reports where id=p_report_id for update;if not found or not public.current_user_has_org(v.organization_id,array['owner','manager']) then raise exception 'permission denied';end if;if v.version<>p_expected_version then raise exception 'report changed; reload' using errcode='40001';end if;if v.status<>'draft' then raise exception 'only draft report can be approved';end if;update public.daily_reports set status='approved',approved_by=auth.uid(),approved_at=now(),updated_by=auth.uid() where id=v.id returning * into v;return v;end $$;
revoke all on function public.approve_daily_report(uuid,integer) from public;grant execute on function public.approve_daily_report(uuid,integer) to authenticated;

create or replace function public.publish_daily_report(p_report_id uuid,p_channel text,p_expected_version integer) returns public.daily_reports language plpgsql security definer set search_path=public,pg_temp as $$
declare v public.daily_reports%rowtype;begin select * into v from public.daily_reports where id=p_report_id for update;if not found or not public.current_user_has_org(v.organization_id,array['owner','manager','staff']) then raise exception 'report not found';end if;if v.version<>p_expected_version then raise exception 'report changed; reload' using errcode='40001';end if;if v.status<>'approved' then raise exception 'only approved report can be marked sent';end if;if length(trim(coalesce(p_channel,'')))<2 then raise exception 'sending channel is required';end if;update public.daily_reports set status='published',published_at=now(),published_by=auth.uid(),published_channel=trim(p_channel),updated_by=auth.uid() where id=v.id returning * into v;return v;end $$;
revoke all on function public.publish_daily_report(uuid,text,integer) from public;grant execute on function public.publish_daily_report(uuid,text,integer) to authenticated;

commit;
